// ---------- shareable hash routing ----------
const routeFromHash = () => {
  if (typeof window === "undefined") return { page: "home", param: null };
  const raw = (window.location.hash || "").replace(/^#\/?/, "");
  const parts = raw.split("/").filter(Boolean);
  if (!parts.length) return { page: "home", param: null };
  const page = parts[0];
  const param = parts[1] ? decodeURIComponent(parts[1]) : null;
  const allowed = new Set(["home","about","books","book","community","library","category","guide","article","workshop","work","privacy","search"]);
  return allowed.has(page) ? { page, param } : { page: "home", param: null };
};

const hashForRoute = (page, param = null) => {
  if (page === "home") return "#/";
  return `#/${page}${param ? `/${encodeURIComponent(param)}` : ""}`;
};

