export default function ArchitectCodex() {
  const [route, setRoute] = useState({ page: "home", param: null });
  const [query, setQuery] = useState("");
  const [menu, setMenu] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);

  const go = (page, param = null) => {
    const next = { page, param };
    setRoute(next);
    setMenu(false);
    if (typeof window !== "undefined") {
      const nextHash = hashForRoute(page, param);
      if (window.location.hash !== nextHash) window.location.hash = nextHash;
      window.scrollTo({ top: 0, behavior: "instant" });
    }
  };

  const dismissModal = () => {
    setModalOpen(false);
    try { localStorage.setItem("codex_entry_seen", "1"); } catch (e) {}
  };

  useEffect(() => {
    const syncRoute = () => {
      setRoute(routeFromHash());
      setMenu(false);
      if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "instant" });
    };
    syncRoute();
    window.addEventListener("hashchange", syncRoute);
    return () => window.removeEventListener("hashchange", syncRoute);
  }, []);

  let body;
  switch (route.page) {
    case "books": body = <Books go={go} />; break;
    case "book": body = <BookDetail slug={route.param} go={go} />; break;
    case "library": body = <Library go={go} />; break;
    case "category": body = <Category id={route.param} go={go} />; break;
    case "guide": body = <GuideDetail slug={route.param} go={go} />; break;
    case "article": body = <ArticleDetail slug={route.param} go={go} />; break;
    case "community": body = <Community go={go} />; break;
    case "workshop": body = <WorkshopPage go={go} />; break;
    case "about": body = <About go={go} />; break;
    case "privacy": body = <Privacy />; break;
    case "search": body = <Search go={go} query={query} setQuery={setQuery} />; break;
    default: body = <Home go={go} />;
  }

  return (
    <div style={styles.app}>
      <style>{globalStyles}</style>
      <div style={styles.bgGradient} />
      <div style={styles.bgNoise} />

      {/* NAV */}
      <header style={styles.nav}>
        <div style={styles.navInner}>
          <div onClick={() => go("home")} style={styles.navBrand} className="navBrandHover">
            <Seal size={26} />
            <span style={styles.navBrandText}>{BRAND}</span>
          </div>
          <nav style={styles.navLinks} className="navLinksDesktop">
            {NAV.filter((n) => n.id !== "workshop" || workshopIsActive()).map((n) => (
              <span
                key={n.id}
                onClick={() => go(n.id)}
                style={{ ...styles.navLink, ...(route.page === n.id ? styles.navLinkActive : {}) }}
                className="navLinkHover"
              >
                {n.label}
              </span>
            ))}
            <span onClick={() => go("search")} style={styles.navSearch} className="navLinkHover">⌕ Search</span>
          </nav>
          <button onClick={() => setMenu(!menu)} style={styles.menuBtn} className="navLinksMobile">{menu ? "✕" : "☰"}</button>
        </div>
        {menu && (
          <div style={styles.mobileMenu}>
            {NAV.filter((n) => n.id !== "workshop" || workshopIsActive()).map((n) => (
              <span key={n.id} onClick={() => go(n.id)} style={styles.mobileLink}>{n.label}</span>
            ))}
            <span onClick={() => go("search")} style={styles.mobileLink}>⌕ Search</span>
          </div>
        )}
      </header>

      <main style={styles.main} key={route.page + (route.param || "")}>
        <div className="pageFade">{body}</div>
      </main>

      {/* FOOTER */}
      <footer style={styles.footer}>
        <div style={styles.footerCols}>
          <div style={styles.footerCol}>
            <div style={styles.footerHead}>Codex</div>
            <span onClick={() => go("home")} style={styles.footerLink} className="footerLinkHover">Home</span>
            <span onClick={() => go("about")} style={styles.footerLink} className="footerLinkHover">About</span>
            <span onClick={() => go("books")} style={styles.footerLink} className="footerLinkHover">Books</span>
            <span onClick={() => go("community")} style={styles.footerLink} className="footerLinkHover">Community</span>
            <span onClick={() => go("library")} style={styles.footerLink} className="footerLinkHover">Library</span>
            {workshopIsActive() && <span onClick={() => go("workshop")} style={styles.footerLink} className="footerLinkHover">Live Workshop</span>}
            <span onClick={() => go("privacy")} style={styles.footerLink} className="footerLinkHover">Privacy</span>
          </div>
          <div style={styles.footerCol}>
            <div style={styles.footerHead}>Find Me</div>
            {SOCIALS.map((s) => (
              <a key={s.name} href={s.url} target="_blank" rel="noopener noreferrer" style={styles.footerLink} className="footerLinkHover">{s.name}</a>
            ))}
          </div>
        </div>
        <div style={styles.footerBottom}>
          <Seal size={22} />
          <a href={`mailto:${CONTACT_EMAIL}`} style={styles.footerEmail}>{CONTACT_EMAIL}</a>
          <div style={styles.footerDisclaimer}>The Architect Codex explores consciousness, reality, meaning, and human experience. It is not medical, psychological, legal, or psychiatric advice.</div>
          <div style={styles.footerCopy}>© {new Date().getFullYear()} {BRAND} · All rights reserved</div>
        </div>
      </footer>
    </div>
  );
}

// =====================================================
// STYLES
// =====================================================
const globalStyles = `
  @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;1,400;1,500&family=EB+Garamond:ital@0;1&family=JetBrains+Mono:wght@400;500&display=swap');
  :root {
    --bg:#0b0a09; --bg2:#100e0c; --ink:#ece4d6; --inkSoft:#bbb1a2; --inkFaint:#857c6f;
    --gold:#c9a84c; --goldBright:#dcc06a;
    --line:rgba(201,168,76,0.20); --lineSoft:rgba(201,168,76,0.10);
    --display:'Cormorant Garamond',serif; --body:'EB Garamond',serif; --mono:'JetBrains Mono',monospace;
  }
  * { box-sizing:border-box; margin:0; padding:0; }
  body { background:var(--bg); color:var(--ink); font-family:var(--body); overflow-x:hidden; }
  ::selection { background:var(--gold); color:var(--bg); }
  @keyframes pageFade { from{opacity:0;transform:translateY(10px);} to{opacity:1;transform:translateY(0);} }
  .pageFade { animation:pageFade 0.6s cubic-bezier(0.16,1,0.3,1) both; }

  .btnPrimaryHover{transition:all .35s cubic-bezier(.16,1,.3,1);}
  .btnPrimaryHover:hover{background:var(--gold)!important;color:var(--bg)!important;transform:translateY(-2px);box-shadow:0 14px 36px -14px rgba(201,168,76,.45);}
  .btnGhostHover{transition:all .35s cubic-bezier(.16,1,.3,1);}
  .btnGhostHover:hover{border-color:var(--gold)!important;color:var(--gold)!important;transform:translateY(-2px);}
  .emailBtnHover{transition:all .3s ease;}
  .emailBtnHover:hover{background:var(--gold)!important;color:var(--bg)!important;}
  .bookCardHover{transition:all .4s cubic-bezier(.16,1,.3,1);cursor:pointer;}
  .bookCardHover:hover{transform:translateY(-6px);}
  .coverArt{transition:box-shadow .4s ease;}
  .bookCardHover:hover .coverArt{box-shadow:0 26px 55px -20px rgba(201,168,76,0.32);}
  .collCardHover,.catCardHover,.discordHover,.socialHover,.resRowHover,.ecoItemHover,.faqHover{transition:all .35s cubic-bezier(.16,1,.3,1);cursor:pointer;}
  .collCardHover:hover,.catCardHover:hover{border-color:var(--line)!important;background:rgba(201,168,76,.04)!important;transform:translateY(-2px);}
  .discordHover:hover,.socialHover:hover{border-color:var(--gold)!important;background:rgba(201,168,76,.05)!important;transform:translateY(-2px);}
  .resRowHover:hover{border-color:var(--line)!important;background:rgba(201,168,76,.03)!important;}
  .resRowHover:hover .resArrow{transform:translateX(6px);}
  .ecoItemHover:hover{color:var(--gold)!important;}
  .catChipHover{transition:all .25s ease;cursor:pointer;}
  .catChipHover:hover{border-color:var(--gold)!important;color:var(--gold)!important;}
  .navLinkHover{transition:color .25s ease;cursor:pointer;}
  .navLinkHover:hover{color:var(--gold)!important;}
  .navBrandHover{cursor:pointer;}
  .footerLinkHover{transition:color .25s ease;cursor:pointer;}
  .footerLinkHover:hover{color:var(--gold)!important;}
  .backHover{transition:color .25s ease;}
  .backHover:hover{color:var(--gold)!important;}
  .faqHover:hover{border-color:var(--line)!important;}
  @keyframes overlayIn{from{opacity:0}to{opacity:1}}
  @keyframes modalIn{from{opacity:0;transform:translateY(16px) scale(.98)}to{opacity:1;transform:none}}
  .modalOverlay{animation:overlayIn .4s ease both;}
  .modalCard{animation:modalIn .55s cubic-bezier(.16,1,.3,1) both;}
  .modalSkipHover{transition:color .25s ease;}
  .modalSkipHover:hover{color:var(--ink)!important;}
  .startHereHover{transition:all .35s cubic-bezier(.16,1,.3,1);}
  .startHereHover:hover{border-color:var(--line)!important;background:rgba(201,168,76,.06)!important;transform:translateY(-2px);}
  .startHereHover:hover .startHereArrow{transform:translateX(6px);}
  .workshopFeatureHover{transition:all .35s cubic-bezier(.16,1,.3,1);}
  input::placeholder{color:var(--inkFaint);}
  input:focus{outline:none;border-color:var(--gold)!important;}
  .navLinksMobile{display:none;}
  ::-webkit-scrollbar{width:6px;} ::-webkit-scrollbar-track{background:transparent;}
  ::-webkit-scrollbar-thumb{background:rgba(201,168,76,.2);border-radius:3px;}
  @media (max-width:780px){
    .navLinksDesktop{display:none!important;}
    .navLinksMobile{display:block!important;}
  }
`;

